// ExtensionInfo.swift - Chrome Extension Model
// Represents a browser extension with its metadata

import Foundation

/// Represents a Chrome extension loaded in the browser
struct ExtensionInfo: Identifiable, Codable, Equatable {
    /// Unique extension ID (generated by Chrome from manifest)
    let id: String
    
    /// Extension display name
    var name: String
    
    /// Extension version string
    var version: String
    
    /// Extension description
    var description: String
    
    /// Absolute path to extension directory
    var path: String
    
    /// Path to extension icon (optional)
    var iconPath: String?
    
    /// URL to extension options page (optional)
    var optionsUrl: String?
    
    /// Whether the extension is currently enabled
    var isEnabled: Bool
    
    /// Coding keys for JSON serialization
    enum CodingKeys: String, CodingKey {
        case id
        case name
        case version
        case description
        case path
        case iconPath
        case optionsUrl
        case isEnabled = "enabled"
    }
    
    init(id: String, name: String, version: String, description: String, 
         path: String, iconPath: String? = nil, optionsUrl: String? = nil, 
         isEnabled: Bool = true) {
        self.id = id
        self.name = name
        self.version = version
        self.description = description
        self.path = path
        self.iconPath = iconPath
        self.optionsUrl = optionsUrl
        self.isEnabled = isEnabled
    }
}
